import { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Select, Input, Table, Button, message, Typography } from 'antd';
import { dataApi } from '../api/client';

const ELIGIBLE_TABLES = [
  'sys_page', 'sys_component', 'sys_server_class', 'sys_client_class', 'sys_client_script',
  'sys_menu', 'sys_menu_item', 'sys_ui_action', 'sys_rest_api', 'sys_db_trigger', 'sys_job',
  'sys_form', 'sys_form_field', 'sys_field_set',
  'sys_workflow_definition', 'sys_workflow_step_definition', 'sys_workflow_transition_definition',
];

export default function ChangeSetPicker() {
  const [params] = useSearchParams();
  const changeSetId = params.get('changeSetId');
  const [table, setTable] = useState('sys_page');
  const [q, setQ] = useState('');
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);

  async function search() {
    setLoading(true);
    try {
      const filters = [];
      if (q) filters.push({ field: 'name', op: 'contains', value: q });
      if ((table === 'sys_form' || table === 'sys_workflow_definition')) {
        filters.push({ field: 'snapshot_of', op: 'is_null', value: true });
      }
      const res = await dataApi.list(table, { filters, limit: 50 });
      setRows(res.data || res.items || res || []);
    } catch (e) {
      message.error('Search failed: ' + (e && e.message ? e.message : e));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { search(); }, [table]);

  async function add(record) {
    try {
      await dataApi.create('sys_change_set_item', {
        change_set_id: changeSetId, table_name: table, record_id: record.id,
        operation: 'upsert', added_reason: 'manual',
      });
      message.success('Added "' + (record.name || record.id) + '"');
    } catch (e) {
      message.warning('Could not add (maybe already in this change set)');
    }
  }

  if (!changeSetId) return <Typography.Text type="danger">Missing changeSetId</Typography.Text>;

  return (
    <div style={{ padding: 24 }}>
      <Typography.Title level={4}>Add Records to Change Set</Typography.Title>
      <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
        <Select value={table} onChange={setTable} style={{ width: 320 }}
          options={ELIGIBLE_TABLES.map((t) => ({ value: t, label: t }))} />
        <Input.Search placeholder="Search by name" value={q} onChange={(e) => setQ(e.target.value)}
          onSearch={search} style={{ width: 320 }} />
      </div>
      <Table
        rowKey="id" loading={loading} dataSource={rows} pagination={false}
        columns={[
          { title: 'Name', dataIndex: 'name', render: (v, r) => v || r.display_name || r.id },
          { title: '', width: 100, render: (_, r) => <Button size="small" onClick={() => add(r)}>Add</Button> },
        ]}
      />
    </div>
  );
}
